	const formatKey = formatOptions ? JSON.stringify(formatOptions) : "";
	useSafeLayoutEffect(() => {
		recorder.setOptions({
			...formatRef.current && { formatOptions: formatRef.current },
			...sequenceTimeoutMs !== void 0 && { sequenceTimeoutMs }
		});
	}, [
		recorder,
		formatKey,
		sequenceTimeoutMs
	]);
